import type { InlineNode } from '@orkestrel/markdown'
import { createMarkdown, flattenText, isCodeSpanNode, isEmphasisNode, isHeadingNode, isImageNode, isLinkNode } from '@orkestrel/markdown'
import { findFirstCode, normalizeIdentifier } from '@orkestrel/guide'

/** Extracts compared inline content while preserving code-token boundaries. */
export function extractCellText(cell: readonly InlineNode[]): string {
	let text = ''
	for (const node of cell) {
		if (isCodeSpanNode(node)) text += `\`${node.value}\``
		else if (isEmphasisNode(node) || isLinkNode(node) || isImageNode(node)) {
			text += extractCellText(node.children)
		} else text += flattenText(node)
	}
	return text
}

/** Extracts an entity name from the proposed heading admission rule. */
export function extractHeading(input: string): string | undefined {
	const block = createMarkdown(input).document.children.find(isHeadingNode)
	if (block === undefined || block.level !== 3) return undefined
	const rawName = findFirstCode(block.children)
	const text = extractCellText(block.children).trim()
	if (rawName === undefined || text !== `\`${rawName}\``) return undefined
	return normalizeIdentifier(rawName)
}

